export const CREDIT = 'Created by Simoné Govender';
const T=(id,paper,title,icon,summary,formula,unit,trap,tip,prerequisite)=>({id,paper,title,icon,summary,formula,unit,trap,tip,prerequisite,credit:CREDIT});
export const topics = [
T('forces',1,'Forces & Newton’s laws','↗','A resultant force changes velocity. Draw a free-body diagram for one object, choose axes, then add the forces along each axis. An object can move at constant velocity while the net force is zero.','F_net = ma','N','Action–reaction forces act on different objects; they do not cancel on one free-body diagram.','Write a separate force equation for each object in a connected system.','Vectors, components and acceleration'),
T('gravity',1,'Universal gravitation','◎','Any two masses attract. The force becomes four times smaller when their centre-to-centre separation doubles. Gravitational field strength is force per unit mass.','F = Gm₁m₂/r²; g = GM/r²','N; m·s⁻²','Use the distance between centres, not just altitude above a planet.','Convert kilometres to metres before squaring the distance.','Scientific notation and inverse-square relationships'),
T('momentum',1,'Momentum & impulse','⇢','Momentum is mass multiplied by velocity, so direction matters. Net impulse equals the change in momentum. Total momentum is conserved when the net external force on the system is zero.','p = mv; F_netΔt = Δp','kg·m·s⁻¹; N·s','A rebound reverses the sign of velocity. The change in momentum can exceed the initial momentum.','State the isolated-system condition before applying conservation.','Signed velocities and Newton’s second law'),
T('projectiles',1,'Vertical projectile motion','↑','Under gravity alone, vertical acceleration is constant and downward throughout the motion, including at the highest point. At the highest point velocity is zero, not acceleration.','v_f = vᵢ + aΔt; Δy = vᵢΔt + ½a(Δt)²','m; m·s⁻¹','Keep your chosen positive direction consistent. A downward displacement can be negative.','Write the sign convention and use g = 9.8 m·s⁻² unless the question says otherwise.','Equations of motion and graph interpretation'),
T('energy',1,'Work, energy & power','⚡','Work transfers energy. Only the force component parallel to displacement contributes to work. Net work equals the change in kinetic energy. Power measures the rate of energy transfer.','W = FΔx cosθ; Wnet = ΔK; P = W/Δt','J; W','Do not use conservation of mechanical energy when friction transfers mechanical energy to thermal energy.','Distinguish work by one force from net work by all forces.','Trigonometry and kinetic energy'),
T('doppler',1,'Doppler effect','◖','Relative motion between a sound source and listener changes the frequency heard. An approaching source compresses the wavefront spacing; a receding source spreads it out.','fL = [(v ± vL)/(v ± vS)]fS','Hz','The wave speed in the medium does not increase because the source moves.','Decide whether the heard frequency should be higher or lower before choosing signs.','Wave speed, frequency and wavelength'),
T('electrostatics',1,'Charges & electric fields','⊕','Like charges repel and unlike charges attract. Electric field direction is the direction of the force on a positive test charge. Add electric forces or fields as vectors.','F = k|q₁q₂|/r²; E = F/q','N; N·C⁻¹','Convert microcoulombs using 10⁻⁶. Distance is squared, charge is not.','Calculate magnitudes, then explain directions using charge signs.','Vectors and scientific notation'),
T('circuits',1,'Circuits & internal resistance','⌁','Current is charge flow per second. Series components carry the same current; parallel branches share potential difference. A real cell loses some energy across its internal resistance.','V = IR; ε = I(R + r)','V; A; Ω','Terminal voltage is less than emf when a cell supplies current.','Simplify the external circuit first, then include internal resistance.','Series and parallel resistance'),
T('machines',1,'Generators & motors','⟳','A generator converts mechanical energy into electrical energy through electromagnetic induction. A motor converts electrical energy into mechanical energy through forces on current-carrying conductors.','εavg = −NΔΦ/Δt; Φ = BA cosθ','V; Wb','The angle in magnetic flux is measured from the normal to the coil, not its plane.','Use the sign in Faraday’s law to explain opposition to the change, not opposition to flux itself.','Magnetic fields and induction'),
T('ac',1,'Alternating current','∿','Alternating current changes direction. RMS values give the equivalent direct-current heating effect in a resistor. For a sinusoidal supply, RMS is peak divided by √2.','Vrms = Vmax/√2; Irms = Imax/√2','V; A','Use RMS values for average power in a resistor, not peak values.','State that the peak-to-RMS relation assumes a sinusoidal waveform.','Electric power and sine waves'),
T('photoelectric',1,'Photoelectric effect & spectra','✦','A photon transfers a discrete energy hf. Electrons are emitted only if photon energy reaches the work function. Above threshold, higher frequency increases maximum kinetic energy; greater intensity increases photon arrival rate.','E = hf; Kmax = hf − W₀','J; Hz','Increasing intensity below threshold does not release electrons in this model.','Convert wavelength to metres and use f = c/λ before calculating photon energy.','Wave frequency and energy conservation'),
T('organic-names',2,'Organic names & groups','⬡','Identify the functional group first. Find a suitable longest carbon chain, number it to give the functional group the lowest permitted locant, and then name branches and unsaturation.','Alkane: CₙH₂ₙ₊₂; alkene: CₙH₂ₙ','molecular formula','A molecular formula alone may represent more than one structural isomer.','Show functional groups clearly when drawing structural formulae.','Carbon bonding and structural formulae'),
T('organic-properties',2,'Organic properties','⋮','Boiling point depends on the energy required to overcome intermolecular forces. Compare hydrogen bonding, dipole interactions and London forces while controlling for size and shape.','Stronger intermolecular attraction → higher boiling point','qualitative comparison','Boiling overcomes intermolecular forces, not the covalent bonds within each molecule.','Link structure → intermolecular forces → energy needed → boiling point.','Polarity and intermolecular forces'),
T('organic-reactions',2,'Organic reactions & polymers','⇌','Use the functional group to identify possible reaction pathways. Addition can consume a double bond; elimination can create one. Esterification combines an alcohol and carboxylic acid under suitable conditions.','Alcohol + carboxylic acid ⇌ ester + water','reaction products','State reagents and conditions; naming only the reaction often misses marks.','Track carbon atoms through the reaction and distinguish substitution from addition.','Functional groups and balancing equations'),
T('rates',2,'Reaction rates & energy','◷','Reaction rate describes change in concentration or amount per time. Higher temperature increases the fraction of collisions with enough energy. A catalyst offers a pathway with lower activation energy.','Rate = |Δc|/Δt; ΔH = Hproducts − Hreactants','mol·dm⁻³·s⁻¹; kJ·mol⁻¹','A catalyst changes neither ΔH nor the equilibrium constant at a fixed temperature.','For temperature explanations, mention both collision frequency and sufficient collision energy.','Collision theory and graphs'),
T('equilibrium',2,'Chemical equilibrium','⇄','In a closed system at equilibrium, forward and reverse reaction rates are equal. Concentrations stay constant but need not be equal. Only temperature changes Kc for a given reaction.','Kc = products / reactants, each raised to stoichiometric powers','Kc expression','Exclude pure solids and liquids from the concentration expression.','Use a change table; distinguish a concentration change from a temperature change.','Balanced equations and concentrations'),
T('acids',2,'Acids, bases & pH','◉','A Brønsted–Lowry acid donates a proton and a base accepts one. Strong acids ionise extensively; concentration describes how much solute is present per volume and is a different idea.','pH = −log[H₃O⁺]; Kw = [H₃O⁺][OH⁻]','mol·dm⁻³','Strong does not mean concentrated. Use Kw = 1.0 × 10⁻¹⁴ only at 25 °C.','Check whether complete ionisation is justified before equating acid concentration and hydronium concentration.','Logarithms and mole concentration'),
T('titrations',2,'Titrations & stoichiometry','⌄','At equivalence, the reacting amounts follow the balanced equation. Convert volumes to dm³, calculate moles, use the coefficient ratio, then find the unknown concentration.','n = cV; nA/a = nB/b','mol; mol·dm⁻³','The endpoint is an observed indicator change; the equivalence point is the stoichiometric condition.','Use the balanced equation; not every titration has a 1:1 ratio.','Moles, balancing and volume units'),
T('galvanic',2,'Galvanic cells & redox','⊖','Spontaneous redox reactions can supply electrical energy. Oxidation occurs at the anode and reduction at the cathode. In a galvanic cell electrons flow externally from negative anode to positive cathode.','E°cell = E°cathode − E°anode','V','Use reduction potentials for both half-cells; do not multiply electrode potentials by coefficients.','A salt bridge conducts ions, not electrons, to maintain electrical neutrality.','Oxidation numbers and half-reactions'),
T('electrolysis',2,'Electrolytic cells','⊞','An external power supply drives a nonspontaneous redox reaction. Oxidation is still at the anode and reduction at the cathode, but in an electrolytic cell the anode is positive and the cathode negative.','Oxidation: electrons lost; reduction: electrons gained','electrode products','Products depend on the electrolyte, concentration and electrode material. Aqueous and molten salts can behave differently.','For refining, distinguish the impure anode from the pure-metal cathode.','Ions, redox and electric current')
];
const f=n=>Number.isInteger(n)?String(n):Number(n.toPrecision(5)).toString();
const sci=n=>n===0?'0':Math.abs(n)<0.001||Math.abs(n)>=1e6?n.toExponential(3):f(n);
const out=(question,known,find,principle,formula,substitution,answer,unit,explain,number=null)=>({question,known,find,steps:[{title:'Choose the principle',text:principle},{title:'Write the relationship',text:formula},{title:'Substitute carefully',text:substitution},{title:'State the answer',text:`${answer}${unit?' '+unit:''}`},{title:'Make sense of it',text:explain}],answer:String(answer),unit,number});
const calc=(q,k,u,p,formula,sub,n,unit,why)=>out(q,k,u,p,formula,sub,sci(n),unit,why,n);
const qualitative=(q,k,find,principle,rule,reason,answer,why)=>out(q,k,find,principle,rule,reason,answer,'',why);


