const EXAM_MARKS={
forces:[4,3,3,3],gravity:[4,4,3,3],momentum:[3,4,5,3],projectiles:[3,3,3,3],energy:[3,4,4,4],
doppler:[4,4,4,3],electrostatics:[4,4,3,3],circuits:[3,4,4,3],machines:[4,3,3,3],ac:[3,3,4,2],
photoelectric:[3,4,4,4],'organic-names':[2,3,2,3],'organic-properties':[3,2,3,3],'organic-reactions':[3,3,3,3],
rates:[3,3,3,3],equilibrium:[4,4,5,5],acids:[3,3,4,4],titrations:[5,6,3,5],galvanic:[4,2,3,3],electrolysis:[2,2,4,3]
};
function examify(topic,e,i){
 const numeric=e.number!==null;
 const mode=i%4;
 const difficulty=i<25?'Exam core':i<75?'Exam application':'Exam stretch';
 const marks=(EXAM_MARKS[topic.id]||[numeric?3:2,numeric?3:2,numeric?3:2,numeric?3:2])[mode];
 const contexts=EXAM_CONTEXTS[topic.id]||['a Grade 12 Physical Sciences examination context'];
 const context=contexts[mode%contexts.length];
 const levelNote=i>=75?'Select the relevant information, justify your method and show all formulae and substitutions.':i>=25?'Show the formula used, the substitution and the final answer with a unit where applicable.':'Work from the stated information and use the appropriate Grade 12 relationship.';
 const directionNote=['forces','momentum','projectiles','electrostatics','doppler'].includes(topic.id)?' Include direction or sign where it is physically meaningful.':'';
 const question='Exam context: '+context+'. '+e.question+' '+levelNote+directionNote;
 return {...e,question,marks,difficulty,examSkill:EXAM_SKILLS[topic.id]||'Grade 12 application',diagramHint:context+'; use the numerical values stated in this exact question',originalExamStyle:true};
}

export function example(id,index=0){
const topic=topics.find(t=>t.id===id)||topics[0];const i=((index%100)+100)%100;const mode=i%4;const n=Math.floor(i/4)+1;const a=2+n,b=3+(n%7),g=9.8;let e;
switch(topic.id){
case 'forces':{
 if(mode===0){const mass=a,F=mass*(2+n/5),fr=b;e=calc(`A ${mass} kg trolley is pulled horizontally with ${f(F)} N. Friction is ${fr} N. Find its acceleration.`,`m = ${mass} kg; F = ${f(F)} N; f = ${fr} N`,'acceleration','Choose the pull direction as positive and apply Newton’s second law.','F − f = ma; a = (F − f)/m',`a = (${f(F)} − ${fr})/${mass}`,(F-fr)/mass,'m·s⁻²','The positive answer means acceleration is in the pull direction.');}
 if(mode===1){const mass=a,mu=(n%6+1)/10;e=calc(`A ${mass} kg block slides across a horizontal surface. μk = ${mu}. Find the kinetic friction magnitude.`,`m = ${mass} kg; μk = ${mu}; g = 9.8 m·s⁻²`,'friction','There is no vertical acceleration, so N = mg.','fk = μkN = μkmg',`fk = ${mu} × ${mass} × 9.8`,mu*mass*g,'N','Friction acts opposite the sliding motion; this is its magnitude.');}
 if(mode===2){const m=a,acc=n/10;e=calc(`A ${m} kg parcel accelerates upward at ${acc} m·s⁻² in a lift. Find the upward normal force.`,`m = ${m} kg; a = +${acc} m·s⁻²; upward positive`,'normal force','The upward normal force must overcome weight and provide upward acceleration.','N − mg = ma; N = m(g + a)',`N = ${m}(9.8 + ${acc})`,m*(g+acc),'N','The normal force is larger than the weight during upward acceleration.');}
 if(mode===3){const m=a,ang=15+n;e=calc(`A ${m} kg block rests on an incline at ${ang}°. Find the component of weight parallel to the incline.`,`m = ${m} kg; θ = ${ang}°`,'parallel weight component','Resolve the weight into components parallel and perpendicular to the plane.','Wparallel = mg sinθ',`Wparallel = ${m} × 9.8 × sin(${ang}°)`,m*g*Math.sin(ang*Math.PI/180),'N','This component points down the incline. Use degree mode.');}break;}
case 'gravity':{const G=6.67e-11,M=5.98e24,R=6.38e6;if(mode===0){const m=a*100,d=b;e=calc(`Two masses of ${m} kg and ${m+100} kg are ${d} m apart. Find the gravitational attraction.`,`G = 6.67 × 10⁻¹¹; m₁ = ${m}; m₂ = ${m+100}; r = ${d} m`,'force magnitude','Apply Newton’s law of universal gravitation.','F = Gm₁m₂/r²',`F = (6.67 × 10⁻¹¹)(${m})(${m+100})/${d}²`,G*m*(m+100)/d**2,'N','Both objects experience equal-magnitude attractive forces.');}if(mode===1){const h=n*100000;e=calc(`Find gravitational field strength at ${n*100} km above Earth. Use M = 5.98 × 10²⁴ kg and R = 6.38 × 10⁶ m.`,`h = ${n*100} km = ${h} m; r = R + h`,'field strength','Use distance from Earth’s centre.','g = GM/(R + h)²',`g = (6.67 × 10⁻¹¹)(5.98 × 10²⁴)/(${R+h})²`,G*M/(R+h)**2,'m·s⁻²','Gravitational acceleration is lower farther from Earth’s centre.');}if(mode===2){const F=a*10,k=1+n/10;e=calc(`Two objects attract with ${F} N. Their separation is increased by a factor of ${k}. Find the new force.`,`F₁ = ${F} N; r₂ = ${k}r₁`,'new force','Masses are unchanged and force is inversely proportional to distance squared.','F₂ = F₁/k²',`F₂ = ${F}/${k}²`,F/k**2,'N','Increasing separation reduces the force.');}if(mode===3){const m=a,field=1+n/5;e=calc(`A ${m} kg instrument is on a moon with g = ${field} m·s⁻². Find its weight.`,`m = ${m} kg; g = ${field} m·s⁻²`,'weight','Weight is gravitational force, not mass.','W = mg',`W = ${m} × ${field}`,m*field,'N','Its mass is still unchanged when moved to another planet.');}break;}
case 'momentum':{if(mode===0){const m=a,u=b,v=-n/2;e=calc(`A ${m} kg trolley moving right at ${u} m·s⁻¹ rebounds left at ${n/2} m·s⁻¹. Find its change in momentum; right is positive.`,`m = ${m}; vᵢ = +${u}; v_f = ${v}`,'change in momentum','Momentum is a vector; the rebound velocity is negative.','Δp = m(v_f − vᵢ)',`Δp = ${m}(${v} − ${u})`,m*(v-u),'kg·m·s⁻¹','The negative sign indicates a change toward the left.');}if(mode===1){const m=a,t=0.2+n/10,u=b;e=calc(`A ${m} kg object slows from ${u} m·s⁻¹ to rest in ${f(t)} s. Find the average net force in the initial positive direction.`,`m = ${m}; vᵢ = ${u}; v_f = 0; Δt = ${f(t)} s`,'average force','Apply the impulse–momentum theorem.','F_avg = m(v_f − vᵢ)/Δt',`F_avg = ${m}(0 − ${u})/${f(t)}`,-m*u/t,'N','A negative force opposes the initial motion.');}if(mode===2){const m1=a,m2=b,u=2+n;e=calc(`A ${m1} kg trolley at ${u} m·s⁻¹ hits a stationary ${m2} kg trolley and they stick. External impulse is negligible. Find their common velocity.`,`m₁ = ${m1}; v₁ᵢ = ${u}; m₂ = ${m2}; v₂ᵢ = 0`,'common velocity','Total momentum is conserved during the isolated collision.','m₁v₁ᵢ + m₂v₂ᵢ = (m₁ + m₂)v_f',`v_f = (${m1} × ${u})/(${m1} + ${m2})`,m1*u/(m1+m2),'m·s⁻¹','The final speed is smaller, but total momentum is unchanged. Kinetic energy is not conserved.');}if(mode===3){const force=a*10,t=n/20;e=calc(`A constant net force of ${force} N acts rightward for ${t} s. Find the impulse.`,`F_net = ${force} N; Δt = ${t} s`,'impulse','Impulse is the area under a net-force versus time graph.','J = F_netΔt',`J = F_netΔt = ${force} × ${t}`,force*t,'N·s','This equals the change in momentum to the right.');}break;}
case 'projectiles':{const u=10+n;if(mode===0)e=calc(`A ball is thrown vertically upward at ${u} m·s⁻¹. Ignoring air resistance, find the time to its highest point.`,`vᵢ = +${u}; v_f = 0; a = −9.8 m·s⁻²`,'time','At maximum height the vertical velocity is zero.','v_f = vᵢ + aΔt; Δt = (v_f − vᵢ)/a',`Δt = (0 − ${u})/(−9.8)`,u/g,'s','Acceleration is still downward at the highest point.');if(mode===1)e=calc(`A ball is launched upward at ${u} m·s⁻¹. Find its maximum height above its launch point.`,`vᵢ = ${u}; v_f = 0; a = −9.8 m·s⁻²`,'maximum displacement','Use the equation without time.','v_f² = vᵢ² + 2aΔy; Δy = (v_f² − vᵢ²)/(2a)',`Δy = −${u}²/[2(−9.8)]`,u*u/(2*g),'m','The positive displacement is above the launch point.');if(mode===2){const t=0.5+n/10;e=calc(`A stone is dropped from rest. Find its downward displacement after ${t} s, before it hits the ground.`,`vᵢ = 0; a = +9.8 m·s⁻²; Δt = ${t} s; downward positive`,'displacement','Constant acceleration acts throughout the fall.','Δy = vᵢΔt + ½a(Δt)²',`Δy = 0 + 0.5 × 9.8 × ${t}²`,0.5*g*t*t,'m','Distance grows with the square of time, not linearly.');}if(mode===3){const t=1+n/10;e=calc(`A ball starts upward at ${u} m·s⁻¹. Find its velocity after ${t} s before landing; upward is positive.`,`vᵢ = +${u}; a = −9.8 m·s⁻²; Δt = ${t} s`,'velocity','Gravity reduces upward velocity continuously.','v_f = vᵢ + aΔt',`v_f = ${u} − 9.8(${t})`,u-g*t,'m·s⁻¹','A negative result would indicate downward motion.');}break;}
case 'energy':{if(mode===0){const F=a*10,d=b,ang=n+10;e=calc(`A ${F} N force pulls a trolley through ${d} m, at ${ang}° above its horizontal displacement. Find work by this force.`,`F = ${F}; Δx = ${d}; θ = ${ang}°`,'work','Only the parallel force component does work.','W = FΔx cosθ',`W = ${F} × ${d} × cos(${ang}°)`,F*d*Math.cos(ang*Math.PI/180),'J','The work is positive because the force component is along the displacement.');}if(mode===1){const m=a,u=b,v=b+3;e=calc(`A ${m} kg trolley increases speed from ${u} to ${v} m·s⁻¹. Find the net work.`,`m = ${m}; vᵢ = ${u}; v_f = ${v}`,'net work','Apply the work–energy theorem to all forces together.','W_net = ½m(v_f² − vᵢ²)',`W_net = 0.5 × ${m}(${v}² − ${u}²)`,.5*m*(v*v-u*u),'J','Net work is positive when kinetic energy increases.');}if(mode===2){const m=a,h=b,t=n+4;e=calc(`A motor lifts ${m} kg through ${h} m at constant speed in ${t} s. Find its useful average power.`,`m = ${m}; h = ${h}; t = ${t}`,'power','Useful work raises gravitational potential energy.','P = mgh/t',`P = ${m} × 9.8 × ${h}/${t}`,m*g*h/t,'W','This is useful output power; input power can be greater if efficiency is below 100%.');}if(mode===3){const h=a;e=calc(`A bead starts from rest ${h} m above the bottom of a frictionless track. Find its speed at the bottom.`,`initial speed = 0; Δh = ${h}; friction negligible`,'speed','Mechanical energy is conserved.','mgh = ½mv²; v = √(2gh)',`v = √(2 × 9.8 × ${h})`,Math.sqrt(2*g*h),'m·s⁻¹','Mass cancels, so the ideal speed does not depend on mass.');}break;}
case 'doppler':{const v=340,fs=400+n*10,s=5+n;if(mode===0)e=calc(`A ${fs} Hz siren approaches a stationary listener at ${s} m·s⁻¹. Sound speed is 340 m·s⁻¹. Find the heard frequency.`,`fS = ${fs}; vS = ${s}; vL = 0; v = 340`,'heard frequency','Approaching wavefronts are closer together.','fL = vfS/(v − vS)',`fL = 340 × ${fs}/(340 − ${s})`,v*fs/(v-s),'Hz','The answer must exceed the source frequency.');if(mode===1)e=calc(`A ${fs} Hz siren moves away from a stationary listener at ${s} m·s⁻¹. Sound speed is 340 m·s⁻¹. Find the heard frequency.`,`fS = ${fs}; vS = ${s}; vL = 0; v = 340`,'heard frequency','Receding wavefronts are farther apart.','fL = vfS/(v + vS)',`fL = 340 × ${fs}/(340 + ${s})`,v*fs/(v+s),'Hz','The answer is below the source frequency.');if(mode===2)e=calc(`A listener travels at ${s} m·s⁻¹ toward a stationary ${fs} Hz source. Sound speed is 340 m·s⁻¹. Find the heard frequency.`,`vL = ${s}; vS = 0; fS = ${fs}`,'heard frequency','The moving listener encounters more wavefronts per second.','fL = (v + vL)fS/v',`fL = (340 + ${s})${fs}/340`,(v+s)*fs/v,'Hz','The source remains stationary, so only the numerator changes.');if(mode===3)e=calc(`A stationary source emits ${fs} Hz sound in air at 340 m·s⁻¹. Find the wavelength.`,`v = 340 m·s⁻¹; f = ${fs} Hz`,'wavelength','Wave speed equals frequency multiplied by wavelength.','λ = v/f',`λ = 340/${fs}`,v/fs,'m','Higher frequency at the same wave speed means shorter wavelength.');break;}
case 'electrostatics':{const k=9e9,q=a*1e-6,r=.1+n/100;if(mode===0){const q2=b*1e-6;e=calc(`Charges of +${a} μC and +${b} μC are ${f(r)} m apart. Find the force magnitude.`,`q₁ = ${a} × 10⁻⁶ C; q₂ = ${b} × 10⁻⁶ C; r = ${f(r)} m`,'force magnitude','Apply Coulomb’s law to point charges.','F = k|q₁q₂|/r²',`F = (9 × 10⁹)(${sci(q)})(${sci(q2)})/${f(r)}²`,k*q*q2/r**2,'N','Both charges are positive, so the interaction is repulsive.');}if(mode===1)e=calc(`Find the electric field magnitude ${f(r)} m from a +${a} μC point charge.`,`Q = ${sci(q)} C; r = ${f(r)} m`,'electric field','Electric field is force per unit positive charge.','E = k|Q|/r²',`E = (9 × 10⁹)(${sci(q)})/${f(r)}²`,k*q/r**2,'N·C⁻¹','The field points away from a positive source charge.');if(mode===2){const E=100+n*20;e=calc(`A +${a} μC charge is in a uniform ${E} N·C⁻¹ electric field to the right. Find its force.`,`q = ${sci(q)} C; E = ${E}`,'electric force','Use the definition of electric field.','F = qE',`F = ${sci(q)} × ${E}`,q*E,'N','The force on a positive charge points in the field direction.');}if(mode===3){const force=a*2,k2=1+n/10;e=calc(`The electrostatic force is ${force} N. Charge values stay fixed while separation is multiplied by ${k2}. Find the new force magnitude.`,`F₁ = ${force}; r₂/r₁ = ${k2}`,'new force','Coulomb’s law is an inverse-square law.','F₂ = F₁/(r₂/r₁)²',`F₂ = ${force}/${k2}²`,force/k2**2,'N','A larger separation produces a smaller force.');}break;}
case 'circuits':{const R=a,V=6+n;if(mode===0)e=calc(`A ${R} Ω resistor has ${V} V across it. Find its current.`,`V = ${V}; R = ${R}`,'current','Apply Ohm’s law for an ohmic resistor at constant temperature.','I = V/R',`I = ${V}/${R}`,V/R,'A','Current increases with voltage when resistance stays fixed.');if(mode===1){const r=.5+n/20;e=calc(`A cell has emf ${V} V, internal resistance ${r} Ω and external resistance ${R} Ω. Find the current.`,`ε = ${V}; R = ${R}; r = ${r}`,'circuit current','The internal resistance is in series with the external circuit.','I = ε/(R + r)',`I = ${V}/(${R} + ${r})`,V/(R+r),'A','Using external resistance alone would overestimate the current.');}if(mode===2)e=calc(`Find the equivalent resistance of ${R} Ω and ${b} Ω resistors connected in parallel.`,`R₁ = ${R}; R₂ = ${b}`,'equivalent resistance','Parallel branches share the same voltage.','1/Rp = 1/R₁ + 1/R₂; Rp = R₁R₂/(R₁ + R₂)',`Rp = (${R} × ${b})/(${R} + ${b})`,R*b/(R+b),'Ω','The equivalent resistance is smaller than either branch resistance.');if(mode===3)e=calc(`A ${R} Ω resistor is connected across a ${V} V ideal supply. Find the power it dissipates.`,`R = ${R}; V = ${V}`,'power','Use the electrical power relation and Ohm’s law.','P = V²/R',`P = ${V}²/${R}`,V*V/R,'W','Power is the rate at which electrical energy is transferred to thermal energy.');break;}
case 'machines':{const N=50+n*10,B=.1+n/100,A=.01+n/1000,dt=.1+n/50;if(mode===0)e=calc(`A ${N}-turn coil has flux per turn change from 0 to ${f(A)} Wb in ${f(dt)} s. Find the magnitude of average induced emf.`,`N = ${N}; ΔΦ = ${f(A)} Wb; Δt = ${f(dt)} s`,'emf magnitude','Apply Faraday’s law; calculate magnitude first.','|ε_avg| = N|ΔΦ|/Δt',`|ε_avg| = ${N} × ${f(A)}/${f(dt)}`,N*A/dt,'V','The induced effect opposes the change in magnetic flux.');if(mode===1)e=calc(`A coil of area ${f(A)} m² has its normal parallel to a ${f(B)} T magnetic field. Find the flux per turn.`,`B = ${f(B)} T; A = ${f(A)} m²; θ = 0°`,'magnetic flux','Flux depends on the angle between the field and area normal.','Φ = BA cosθ',`Φ = ${f(B)} × ${f(A)} × cos0°`,B*A,'Wb','Flux is maximum when the field passes straight through the coil.');if(mode===2){const P=100+n*10,eff=60+n;e=calc(`A motor takes ${P} W electrical input and is ${eff}% efficient. Find its useful mechanical output power.`,`Pin = ${P} W; η = ${eff}/100`,'output power','Efficiency is useful output divided by input.','Pout = ηPin',`Pout = ${eff/100} × ${P}`,P*eff/100,'W','The remaining input power is dissipated, for example as heat.');}if(mode===3){const V=a,I=n/10;e=calc(`A generator supplies ${V} V at ${I} A to a resistive load. Find the electrical output power.`,`V = ${V}; I = ${I}`,'electrical power','Power equals energy transferred per unit charge times charge flow rate.','P = VI',`P = ${V} × ${I}`,V*I,'W','A real generator needs greater mechanical input power because of losses.');}break;}
case 'ac':{const max=100+n*10,R=a*10;if(mode===0)e=calc(`A sinusoidal AC supply has peak voltage ${max} V. Find its RMS voltage.`,`Vmax = ${max} V`,'RMS voltage','For sinusoidal voltage, RMS equals peak divided by √2.','Vrms = Vmax/√2',`Vrms = ${max}/√2`,max/Math.SQRT2,'V','This RMS voltage gives the same average resistor heating as that DC voltage.');if(mode===1){const rms=n+2;e=calc(`A sinusoidal current has RMS value ${rms} A. Find its peak value.`,`Irms = ${rms} A`,'peak current','Rearrange the sinusoidal peak–RMS relationship.','Imax = √2 Irms',`Imax = √2 × ${rms}`,Math.SQRT2*rms,'A','The peak value is greater than the RMS value.');}if(mode===2)e=calc(`A ${R} Ω resistor is connected to ${max} V RMS. Find its average power.`,`R = ${R}; Vrms = ${max}`,'average power','For a resistor, RMS values can be used directly for average power.','Pavg = Vrms²/R',`Pavg = ${max}²/${R}`,max*max/R,'W','Do not substitute the peak voltage into this RMS formula.');if(mode===3){const hz=25+n;e=calc(`A sinusoidal supply has frequency ${hz} Hz. Find its period.`,`f = ${hz} Hz`,'period','The period is the time for one complete cycle.','T = 1/f',`T = 1/${hz}`,1/hz,'s','Higher frequency means shorter cycle duration.');}break;}
case 'photoelectric':{const h=6.63e-34,c=3e8,freq=(6+n/5)*1e14,W=2e-19;if(mode===0)e=calc(`Find the energy of a photon with frequency ${sci(freq)} Hz. Use h = 6.63 × 10⁻³⁴ J·s.`,`f = ${sci(freq)} Hz`,'photon energy','A photon carries a discrete energy proportional to frequency.','E = hf',`E = (6.63 × 10⁻³⁴)(${sci(freq)})`,h*freq,'J','Doubling frequency doubles photon energy.');if(mode===1)e=calc(`Light at ${sci(freq)} Hz strikes a metal with work function 2.0 × 10⁻¹⁹ J. Find maximum electron kinetic energy.`,`h = 6.63 × 10⁻³⁴; f = ${sci(freq)}; W₀ = 2.0 × 10⁻¹⁹ J`,'maximum kinetic energy','Photon energy first overcomes the work function.','Kmax = hf − W₀',`Kmax = (6.63 × 10⁻³⁴)(${sci(freq)}) − 2.0 × 10⁻¹⁹`,h*freq-W,'J','A positive result permits emission; if hf < W₀ there would be no photoelectrons.');if(mode===2){const work=(2+n/10)*1e-19;e=calc(`A metal has work function ${sci(work)} J. Find its threshold frequency.`,`W₀ = ${sci(work)} J; h = 6.63 × 10⁻³⁴`,'threshold frequency','At threshold the maximum emitted kinetic energy is zero.','f₀ = W₀/h',`f₀ = ${sci(work)}/(6.63 × 10⁻³⁴)`,work/h,'Hz','Below this frequency, increasing intensity alone does not cause emission.');}if(mode===3){const nm=300+n*5;e=calc(`Find the photon energy of light with wavelength ${nm} nm.`,`λ = ${nm} × 10⁻⁹ m; c = 3.0 × 10⁸; h = 6.63 × 10⁻³⁴`,'photon energy','Combine the wave relationship with the photon energy equation.','E = hc/λ',`E = (6.63 × 10⁻³⁴)(3.0 × 10⁸)/(${nm} × 10⁻⁹)`,h*c/(nm*1e-9),'J','A shorter wavelength corresponds to a higher-energy photon.');}break;}
case 'rates':{if(mode===0){const change=.1+n/100,time=a*10;e=calc(`A reactant concentration falls by ${f(change)} mol·dm⁻³ in ${time} s. Find the average rate of disappearance.`,`|Δc| = ${f(change)}; Δt = ${time}`,'average rate','Use the magnitude of concentration change for disappearance rate.','Rate = |Δc|/Δt',`Rate = ${f(change)}/${time}`,change/time,'mol·dm⁻³·s⁻¹','This is an average over the interval, not necessarily the instantaneous rate.');}if(mode===1){const react=50+n,prod=20+n/2;e=calc(`An energy profile has reactants at ${react} kJ·mol⁻¹ and products at ${prod} kJ·mol⁻¹. Find ΔH.`,`Hreactants = ${react}; Hproducts = ${prod}`,'enthalpy change','Compare final and initial chemical potential energy.','ΔH = Hproducts − Hreactants',`ΔH = ${prod} − ${react}`,prod-react,'kJ·mol⁻¹','The negative sign means the reaction is exothermic.');}if(mode===2){const react=20+n,peak=100+n*2;e=calc(`Reactants lie at ${react} kJ·mol⁻¹ and the transition state at ${peak} kJ·mol⁻¹. Find forward activation energy.`,`Hreactants = ${react}; Hpeak = ${peak}`,'activation energy','Activation energy is the energy gap from reactants to the transition state.','E_a = H_peak − H_reactants',`E_a = ${peak} − ${react}`,peak-react,'kJ·mol⁻¹','Particles need sufficient energy for effective collisions.');}if(mode===3){const v=40+n*5,t=10+n;e=calc(`A reaction collects ${v} cm³ of gas in ${t} s. Find its average gas-production rate.`,`ΔV = ${v} cm³; Δt = ${t} s`,'average gas rate','A measured volume change per time can track gas formation under fixed measurement conditions.','Rate = ΔV/Δt',`Rate = ${v}/${t}`,v/t,'cm³·s⁻¹','Keep measurement conditions constant when comparing gas-volume rates.');}break;}
case 'equilibrium':{const x=.1+n/100,y=.2+n/100;if(mode===0)e=calc(`For H₂(g) + I₂(g) ⇌ 2HI(g), equilibrium concentrations are [H₂]=${f(x)}, [I₂]=${f(x)}, [HI]=${f(y)} mol·dm⁻³. Calculate Kc.`,`[H₂]=[I₂]=${f(x)}; [HI]=${f(y)}`,'Kc','Concentration powers equal the balanced coefficients.','Kc = [HI]²/([H₂][I₂])',`Kc = ${f(y)}²/(${f(x)} × ${f(x)})`,y*y/(x*x),'','Use equilibrium concentrations, not initial concentrations.');if(mode===1)e=calc(`For N₂O₄(g) ⇌ 2NO₂(g), [N₂O₄]=${f(x)} and [NO₂]=${f(y)} mol·dm⁻³ at equilibrium. Calculate Kc.`,`[N₂O₄]=${f(x)}; [NO₂]=${f(y)}`,'Kc','The product concentration is squared because its coefficient is two.','Kc = [NO₂]²/[N₂O₄]',`Kc = ${f(y)}²/${f(x)}`,y*y/x,'','Changing temperature would change this equilibrium constant.');if(mode===2){const initial=1+n/10,reacted=.1+n/100;e=calc(`Initially ${f(initial)} mol H₂ and excess I₂ react in a sealed 2 dm³ vessel: H₂ + I₂ ⇌ 2HI. If ${f(reacted)} mol H₂ reacts, find [HI] formed at equilibrium, starting with no HI.`,`n(H₂ reacted)=${f(reacted)} mol; V=2 dm³; initial HI=0`,'HI concentration','Use the stoichiometric ratio before dividing by volume.','n(HI)=2n(H₂ reacted); c=n/V',`[HI] = [2 × ${f(reacted)}]/2`,reacted,'mol·dm⁻³','The factor of two comes from the balanced chemical equation.');}if(mode===3){const initial=.5+n/20,end=.1+n/100;e=calc(`N₂O₄ ⇌ 2NO₂ starts with [N₂O₄]=${f(initial)} mol·dm⁻³ and no NO₂. At equilibrium [N₂O₄]=${f(end)}. Find [NO₂] at constant volume.`,`initial N₂O₄=${f(initial)}; final=${f(end)}`,'equilibrium NO₂ concentration','For each mole of N₂O₄ consumed, two moles of NO₂ form.','[NO₂]eq = 2([N₂O₄]initial − [N₂O₄]eq)',`[NO₂]eq = 2(${f(initial)} − ${f(end)})`,2*(initial-end),'mol·dm⁻³','Use the change, not the initial amount, to calculate product formed.');}break;}
case 'acids':{const c=(1+n/10)*1e-3;if(mode===0)e=calc(`A dilute strong monoprotic acid has [H₃O⁺]=${sci(c)} mol·dm⁻³. Find its pH.`,`[H₃O⁺]=${sci(c)}`,'pH','Apply the definition of pH.','pH = −log₁₀[H₃O⁺]',`pH = −log₁₀(${sci(c)})`,-Math.log10(c),'','A pH below seven is acidic at 25 °C.');if(mode===1){const ph=2+n/10;e=calc(`A solution has pH ${ph}. Find its hydronium concentration.`,`pH=${ph}`,'hydronium concentration','Invert the base-ten logarithm.','[H₃O⁺] = 10⁻ᵖᴴ',`[H₃O⁺] = 10^(−${ph})`,10**(-ph),'mol·dm⁻³','A one-unit pH decrease corresponds to ten times more hydronium.');}if(mode===2)e=calc(`At 25 °C, a solution has [OH⁻]=${sci(c)} mol·dm⁻³. Find [H₃O⁺].`,`Kw=1.0 × 10⁻¹⁴; [OH⁻]=${sci(c)}`,'hydronium concentration','At a specified temperature, the ion product of water is fixed.','[H₃O⁺] = Kw/[OH⁻]',`[H₃O⁺] = 1.0 × 10⁻¹⁴/${sci(c)}`,1e-14/c,'mol·dm⁻³','The small hydronium concentration is consistent with a basic solution.');if(mode===3)e=calc(`A fully dissociated NaOH solution has concentration ${sci(c)} mol·dm⁻³ at 25 °C. Find pH.`,`[OH⁻]=${sci(c)}; pH+pOH=14 at 25 °C`,'pH','Calculate pOH first, then use the water ion-product relationship.','pOH = −log[OH⁻]; pH = 14 − pOH',`pH = 14 + log₁₀(${sci(c)})`,14+Math.log10(c),'','The pH should be above seven.');break;}
case 'titrations':{const V=20+n,c=.05+n/100;if(mode===0)e=calc(`${V} cm³ of ${f(c)} mol·dm⁻³ HCl is neutralised by 25 cm³ NaOH. Find the NaOH concentration.`,`HCl + NaOH → NaCl + H₂O; VA=${V/1000} dm³; VB=0.025 dm³`,'base concentration','The balanced reaction has a 1:1 mole ratio.','cB = cAVA/VB',`cB = ${f(c)} × ${V/1000}/0.025`,c*V/25,'mol·dm⁻³','At equivalence the acid and base moles are equal for this equation.');if(mode===1)e=calc(`${V} cm³ of ${f(c)} mol·dm⁻³ H₂SO₄ neutralises 25 cm³ NaOH. Find [NaOH], assuming both acidic protons react completely.`,`H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O; VA=${V/1000}; VB=0.025`,'base concentration','Two moles of NaOH react per mole of sulfuric acid.','cB = 2cAVA/VB',`cB = 2 × ${f(c)} × ${V/1000}/0.025`,2*c*V/25,'mol·dm⁻³','The factor of two must follow the balanced equation, not a memorised 1:1 formula.');if(mode===2){const volume=100+n*10;e=calc(`How many moles of solute are in ${volume} cm³ of a ${f(c)} mol·dm⁻³ solution?`,`c=${f(c)}; V=${volume/1000} dm³`,'moles','Concentration is moles per dm³.','n = cV',`n = ${f(c)} × ${volume/1000}`,c*volume/1000,'mol','Using cm³ directly would make the result 1,000 times too large.');}if(mode===3){const mass=1+n/10;e=calc(`${mass} g NaOH (M = 40 g·mol⁻¹) is dissolved to make 250 cm³ solution. Find its concentration.`,`m=${mass} g; M=40 g·mol⁻¹; V=0.250 dm³`,'concentration','Convert mass to moles before dividing by solution volume.','n=m/M; c=n/V = m/(MV)',`c = ${mass}/(40 × 0.250)`,mass/10,'mol·dm⁻³','Use final solution volume, not the volume of water added.');}break;}
case 'galvanic':{const pairs=[['Zn²⁺/Zn',-.76,'Cu²⁺/Cu',.34],['Mg²⁺/Mg',-2.37,'Cu²⁺/Cu',.34],['Fe²⁺/Fe',-.44,'Ag⁺/Ag',.80],['Zn²⁺/Zn',-.76,'Ag⁺/Ag',.80],['Mg²⁺/Mg',-2.37,'Zn²⁺/Zn',-.76]];const p=pairs[(n-1)%5],count=1+Math.floor((n-1)/5);if(mode===0)e=calc(`A battery contains ${count} identical ${p[0]}–${p[2]} galvanic cells in series. Given E°red = ${p[1]} V and ${p[3]} V respectively, find the ideal total emf.`,`anode reduction potential=${p[1]}; cathode=${p[3]}; cells=${count}`,'total emf','The more positive reduction potential is the cathode for this spontaneous cell. Series emfs add.','E°_cell = E°_cathode − E°_anode; E_total = NE°_cell',`E_total = ${count}[${p[3]} − (${p[1]})]`,count*(p[3]-p[1]),'V','Coefficients used to balance electrons do not multiply the individual electrode potentials.');if(mode===1)e=qualitative(`For a ${p[0]} and ${p[2]} cell operating for ${count} minutes, identify the oxidation electrode. Reduction potentials are ${p[1]} V and ${p[3]} V.`,`two reduction potentials; elapsed time does not determine the electrode`,'oxidation electrode','The half-cell with the lower reduction potential runs in reverse.','Oxidation occurs at the anode.',`${p[1]} < ${p[3]}, so the ${p[0]} half-cell is oxidised.`,`${p[0]} is the anode.`,'Electrode identity follows the redox tendency, not elapsed time.');if(mode===2)e=qualitative(`A diagram labels the ${p[0]} half-cell A and ${p[2]} half-cell B in a battery of ${count} cells. In one operating cell, which way do electrons flow externally?`,`A: E°=${p[1]}; B: E°=${p[3]}`,'electron-flow direction','Oxidation releases electrons and reduction uses them.','External electrons travel anode → cathode.',`A has the lower reduction potential and is the anode.`,'From A to B through the external conductor.','Ions carry charge in the electrolyte; electrons do not flow through the salt bridge.');if(mode===3){const current=.1*n,t=60*count;e=calc(`A ${p[0]}–${p[2]} cell supplies ${f(current)} A for ${t} s. Find the charge transferred through the wire.`,`I=${f(current)} A; t=${t} s`,'charge','Current is the rate of charge flow.','Q = IΔt',`Q = ${f(current)} × ${t}`,current*t,'C','This charge moves through the external circuit while ions maintain solution neutrality.');}break;}
case 'electrolysis':{const cells=[['molten NaCl','Na⁺ + e⁻ → Na','2Cl⁻ → Cl₂ + 2e⁻','sodium','chlorine'],['molten MgCl₂','Mg²⁺ + 2e⁻ → Mg','2Cl⁻ → Cl₂ + 2e⁻','magnesium','chlorine'],['molten PbBr₂','Pb²⁺ + 2e⁻ → Pb','2Br⁻ → Br₂ + 2e⁻','lead','bromine'],['copper(II) sulfate with copper electrodes','Cu²⁺ + 2e⁻ → Cu','Cu → Cu²⁺ + 2e⁻','copper','copper ions'],['copper refining with a copper(II) electrolyte','Cu²⁺ + 2e⁻ → Cu','Cu → Cu²⁺ + 2e⁻','pure copper','copper ions']];const c=cells[(n-1)%5],time=1+Math.floor((n-1)/5);if(mode===0)e=qualitative(`During ${time} minutes of electrolysis of ${c[0]}, give the cathode half-reaction.`,`electrolyte=${c[0]}; external supply connected`,'cathode reaction','Cations gain electrons at the negative cathode.','Reduction is gain of electrons.',`Identify the reducible metal ion in this specified electrolyte.`,c[1],`The cathode product is ${c[3]}. Time changes quantity deposited, not the half-reaction.`);if(mode===1)e=qualitative(`During ${time} minutes of electrolysis of ${c[0]}, give the anode half-reaction.`,`electrolyte=${c[0]}; electrode type as stated`,'anode reaction','Oxidation takes place at the positive anode.','Oxidation is loss of electrons.',`Use the named electrode material; copper electrodes can dissolve.`,c[2],`The anode produces ${c[4]}; these conditions must not be silently replaced with aqueous inert-electrode conditions.`);if(mode===2)e=qualitative(`An electrolytic ${c[0]} cell has run for ${time} minutes. State the electrode signs and explain why it needs an external supply.`,`cell is electrolytic`,'signs and energy source','Electrical energy drives a nonspontaneous chemical change.','Cathode = reduction; anode = oxidation.',`The supply pushes electrons toward the cathode and removes them from the anode.`,'Cathode negative; anode positive.','The definitions of oxidation and reduction remain unchanged from galvanic cells.');if(mode===3){const I=.2*n,t=60*time;e=calc(`An electrolytic ${c[0]} cell draws ${f(I)} A for ${t} s. Calculate charge passed.`,`I=${f(I)}; Δt=${t}`,'charge passed','Use current as charge flow per unit time.','Q = IΔt',`Q = ${f(I)} × ${t}`,I*t,'C','Electrode products still depend on the specified electrolyte and electrode materials.');}break;}
default:{
const compounds=[['ethane','alkane','C₂H₆','single C–C bonds','ethene'],['propane','alkane','C₃H₈','single C–C bonds','propene'],['butane','alkane','C₄H₁₀','single C–C bonds','but-1-ene'],['ethene','alkene','C₂H₄','C=C double bond','ethane'],['propene','alkene','C₃H₆','C=C double bond','propane'],['but-1-ene','alkene','C₄H₈','C=C double bond','butane'],['ethanol','alcohol','C₂H₆O','hydroxyl (–OH)','ethene'],['propan-1-ol','alcohol','C₃H₈O','hydroxyl (–OH)','propene'],['butan-1-ol','alcohol','C₄H₁₀O','hydroxyl (–OH)','but-1-ene'],['ethanoic acid','carboxylic acid','C₂H₄O₂','carboxyl (–COOH)','ethyl ethanoate']];
const c=compounds[i%10],task=Math.floor(i/10);const carbon=Number(c[2].match(/C([₂₃₄])/)[1].replace('₂','2').replace('₃','3').replace('₄','4'));
if(topic.id==='organic-names'){
 const qs=[['Identify the homologous series',c[1],`The defining structural feature is ${c[3]}.`],['State the molecular formula',c[2],'Count each element in one molecule; do not confuse molecular and empirical formulae.'],['Identify the characteristic bond or functional group',c[3],'A functional group controls many characteristic reactions.'],['State the number of carbon atoms',String(carbon),'Read the parent prefix and confirm it against the formula.'],['Explain what the parent prefix tells you',`${carbon} carbon atoms in the parent chain.`,'Eth-, prop- and but- correspond to two, three and four carbon atoms.'],['Is this compound a hydrocarbon?',c[1]==='alkane'||c[1]==='alkene'?'Yes. It contains only carbon and hydrogen.':'No. It also contains oxygen.','A hydrocarbon contains only C and H, regardless of whether it is saturated.'],['Identify the elements present',c[2].includes('O')?'Carbon, hydrogen and oxygen.':'Carbon and hydrogen.','Use element symbols in the molecular formula.'],['Is there a carbon–carbon double bond?',c[1]==='alkene'?'Yes; it is an alkene.':'No carbon–carbon double bond is present in this named compound.','A C=O group is different from a C=C bond.'],['Does the compound contain a hydroxyl group?',c[1]==='alcohol'?'Yes, as its alcohol functional group.':c[1]==='carboxylic acid'?'Its –OH is part of a carboxyl group; classify it as a carboxylic acid.':'No.','Classify the complete functional group rather than one piece of it.'],['Explain why its molecular formula alone may be insufficient to name an unknown',`The name ${c[0]} fixes the structure; a formula may be shared by structural isomers.`,'Use a structural formula to locate bonds, branches and functional groups.']][task];
 e=qualitative(`${qs[0]} for ${c[0]}.`,`Compound: ${c[0]}`,'structural classification','Identify the parent chain and defining functional group.','Use systematic organic nomenclature.',qs[2],qs[1],`For ${c[0]}, the characteristic feature is ${c[3]}.`);
}else if(topic.id==='organic-properties'){
const hydrogen=c[1]==='alcohol'||c[1]==='carboxylic acid';const qs=[['Explain the strongest relevant intermolecular attraction in a pure sample.',hydrogen?'Hydrogen bonding, alongside other intermolecular attractions.':'London dispersion forces dominate for this hydrocarbon.'],['Explain what happens to intermolecular attractions during boiling.','Particles gain enough energy to separate against intermolecular attractions.'],['Are intramolecular covalent bonds normally broken during boiling?','No. The molecules remain chemically intact during ordinary boiling.'],['Predict the general boiling-point effect of a longer chain in the same homologous series.','Boiling point generally rises as larger molecules have stronger London forces.'],['Predict the general effect of more branching among comparable chain isomers.','Greater branching generally lowers boiling point because contact area is reduced.'],['Predict the effect of higher temperature on evaporation rate under otherwise identical conditions.','Evaporation generally speeds up because more particles have enough kinetic energy to escape.'],['Explain why boiling point alone cannot establish a unique structural formula.','Different structures may have similar boiling points; use additional chemical or spectroscopic evidence.'],['Would stronger intermolecular attractions generally increase or decrease vapour pressure at the same temperature?','Decrease vapour pressure: fewer particles escape into the gas phase.'],['Describe a fair comparison of boiling points within its homologous series.','Keep external pressure constant and compare known structures, considering chain length and branching.'],['Explain whether it can donate hydrogen bonds in a pure sample.',hydrogen?'Yes. Its O–H group can donate hydrogen bonds.':'No. It has no O–H, N–H or F–H donor group.']][task];
e=qualitative(`For ${c[0]}: ${qs[0]}`,`Structure contains ${c[3]}.`,'property explanation','Connect structure to attractions between molecules.','Structure → attraction → energy required → observed property.',`Identify ${c[1]} as the homologous series, then consider polarity and O–H groups.`,qs[1],'State comparison conditions and distinguish trends from a measured boiling-point value.');
}else{
const saturated=c[1]==='alkane',alkene=c[1]==='alkene',alcohol=c[1]==='alcohol';const route=alkene?`Hydrogenation with H₂ and a suitable metal catalyst gives ${c[4]}.`:alcohol?`Dehydration with heat and a suitable concentrated acid gives ${c[4]} and water.`:saturated?'Halogen substitution can occur in UV light.':'Esterification with ethanol under acid catalysis forms ethyl ethanoate and water.';
const qs=[['Suggest a suitable reaction and its conditions.',route],['Would it undergo simple addition across a C=C bond?',alkene?'Yes. It contains a carbon–carbon double bond.':'Not directly by that route: this compound has no C=C bond.'],['Explain whether it is a suitable simple addition-polymer monomer.',alkene?'Its double bond can open to form an addition polymer chain.':'It lacks the required C=C bond for this simple addition-polymer route.'],['Predict products of complete combustion in sufficient oxygen.','Carbon dioxide and water.'],['Explain why atom conservation matters in writing its reaction equation.','Each element must have equal atom counts before and after the reaction.'],['Explain whether UV light is a typical condition for its alkane halogen substitution.',saturated?'Yes: UV light initiates halogen substitution in an alkane.':'That condition describes alkane substitution; use conditions appropriate to this functional group.'],['Can it act as the alcohol reactant in esterification?',alcohol?'Yes, it supplies the alcohol component.':c[1]==='carboxylic acid'?'It supplies the acid component, not the alcohol component.':'No, it is not an alcohol.'],['Explain whether dehydration is an appropriate alcohol-elimination pathway.',alcohol?`Yes. Under suitable conditions it loses water to form ${c[4]}.`:'This is not an alcohol, so that specific alcohol pathway does not apply.'],['Explain why reagent and condition details must accompany a proposed product.','Different conditions can favour different reactions or isomers; the product cannot be determined from a name alone.'],['Distinguish physical boiling from a chemical reaction of this compound.','Boiling changes physical state; a chemical reaction changes molecular bonding and forms different substances.']][task];
e=qualitative(`For ${c[0]}: ${qs[0]}`,`Homologous series: ${c[1]}; feature: ${c[3]}`,'reaction reasoning','Use the functional group to identify chemically possible transformations.','Track bonds, atoms, reagents and reaction conditions.',route,qs[1],'Do not assume every organic compound undergoes the same reaction.');
}break;}
}
e=examify(topic,e,i);return {...e,id:`${topic.id}-${i+1}`,topic:topic.id,paper:topic.paper,index:i,credit:CREDIT,trap:topic.trap,tip:topic.tip,review:'Original exam-style practice · educator review available',variant:mode+1};
}

export const glossary = [
['Acceleration','Rate of change of velocity.'],['Net force','The vector sum of all forces acting on an object.'],['Impulse','Product of net force and the time interval, equal to change in momentum.'],['Momentum','The product of an object’s mass and velocity.'],['Work function','Minimum energy required to remove an electron from a metal surface.'],['Threshold frequency','Minimum light frequency needed to eject electrons from a particular surface.'],['EMF','Energy supplied per unit charge by a source.'],['RMS','Root mean square: the equivalent DC value for resistor heating.'],['Oxidation','Loss of electrons.'],['Reduction','Gain of electrons.'],['Electrolyte','A substance whose mobile ions can carry electric current.'],['Dynamic equilibrium','A closed-system state with equal forward and reverse reaction rates.'],['Catalyst','A substance that provides an alternative reaction pathway with lower activation energy and is regenerated overall.'],['Activation energy','Minimum energy required for a reaction to occur for a given pathway.'],['Strong acid','An acid that ionises essentially completely in aqueous solution under the stated conditions.'],['Concentration','Amount of solute per unit volume of solution.'],['Homologous series','Organic compounds with the same functional group and general formula and a successive CH₂ difference.'],['Structural isomers','Compounds with the same molecular formula but different arrangements of bonds.'],['Equivalence point','The point in a titration when reactants have combined in their stoichiometric ratio.'],['Normal force','The perpendicular contact force exerted by a surface.']
];

